package store

import (
	"sort"
	"time"
)

// IdempotencyTTL is how long a kept response is replayed; after that its key counts as new.
const IdempotencyTTL = 24 * time.Hour

// IdempotencyRecord is the response kept for an Idempotency-Key of an organization, with a fingerprint of the request it
// answered.
type IdempotencyRecord struct {
	OrgID       string    `json:"org_id"`
	Key         string    `json:"key"`
	Fingerprint string    `json:"fingerprint"`
	Status      int       `json:"status"`
	Body        []byte    `json:"body"`
	KeptAt      time.Time `json:"kept_at"`
}

// IdempotencyState is the outcome of BeginIdempotency.
type IdempotencyState int

// Outcomes of BeginIdempotency.
const (
	IdempotencyNew      IdempotencyState = iota // the key is reserved for the caller, who must keep or release it
	IdempotencyReplay                           // a kept response exists for the same request
	IdempotencyMismatch                         // the key was used for another request
	IdempotencyInFlight                         // a request with the key is still being handled
)

type idemKey struct{ org, key string }

// BeginIdempotency reserves key for a request with the given fingerprint in orgID. It does not wait: when a request with
// the key is still being handled it returns IdempotencyInFlight. A kept response for the same fingerprint is returned as
// IdempotencyReplay; one for another fingerprint is IdempotencyMismatch.
func (s *Store) BeginIdempotency(orgID, key, fingerprint string, now time.Time) (IdempotencyRecord, IdempotencyState) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := idemKey{orgID, key}
	if fp, ok := s.idemPending[k]; ok {
		if fp != fingerprint {
			return IdempotencyRecord{}, IdempotencyMismatch
		}
		return IdempotencyRecord{}, IdempotencyInFlight
	}
	if r, ok := s.idem[k]; ok {
		if now.Before(r.KeptAt.Add(IdempotencyTTL)) {
			if r.Fingerprint != fingerprint {
				return IdempotencyRecord{}, IdempotencyMismatch
			}
			return r, IdempotencyReplay
		}
		delete(s.idem, k)
	}
	s.idemPending[k] = fingerprint
	return IdempotencyRecord{}, IdempotencyNew
}

// KeepIdempotency keeps the response for a key reserved by BeginIdempotency, so that it is replayed.
func (s *Store) KeepIdempotency(orgID, key string, status int, body []byte, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := idemKey{orgID, key}
	s.idem[k] = IdempotencyRecord{OrgID: orgID, Key: key, Fingerprint: s.idemPending[k], Status: status,
		Body: append([]byte(nil), body...), KeptAt: now.UTC()}
	delete(s.idemPending, k)
}

// ReleaseIdempotency frees a key reserved by BeginIdempotency without keeping a response, so that a retry runs again.
func (s *Store) ReleaseIdempotency(orgID, key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.idemPending, idemKey{orgID, key})
}

// idempotencyRecords returns the kept responses, sorted by organization and key. The caller holds the lock.
func (s *Store) idempotencyRecords() []IdempotencyRecord {
	var out []IdempotencyRecord
	for _, r := range s.idem {
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].OrgID != out[j].OrgID {
			return out[i].OrgID < out[j].OrgID
		}
		return out[i].Key < out[j].Key
	})
	return out
}

