package api_test

import (
	"net/http"
	"strings"
	"sync"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// openInvoice creates an open invoice of 40.00 for a new customer of org.
func openInvoice(t *testing.T, e *apitest.Env, org apitest.Org, email string) store.Invoice {
	t.Helper()
	c := e.CreateCustomer(org, "Jane", email)
	inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: org.ID, CustomerID: c.ID, Currency: money.USD,
		Lines: []store.Line{{Description: "Pro", Quantity: 1, UnitAmount: 4000}}}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	return inv
}

func payPath(inv store.Invoice) string { return "/v1/invoices/" + inv.ID + "/pay" }

// withKey is the request headers that carry an Idempotency-Key.
func withKey(key string) http.Header { return http.Header{"Idempotency-Key": {key}} }

var visa = map[string]string{"payment_method": "pm_card_visa"}

func TestPayReplaysKeptResponse(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	first := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("pay-1"))
	if first.Code != http.StatusOK || first.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("first pay: %s", first)
	}
	again := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("pay-1"))
	if again.Code != http.StatusOK || again.Header.Get("Idempotent-Replayed") != "true" || string(again.Body) != string(first.Body) {
		t.Fatalf("retry = %s, want the first response again (%s)", again, first)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

func TestIdempotencyKeyValidation(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	for _, key := range []string{"", strings.Repeat("k", 256), "tab\there", "naïve", "new\nline"} {
		if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey(key)); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_idempotency_key" {
			t.Fatalf("key %q: %s", key, r)
		}
	}
	if n := len(e.Gateway.Calls()); n != 0 {
		t.Fatalf("%d charge attempts for invalid keys, want 0", n)
	}
	for _, key := range []string{"k", strings.Repeat("k", 255), "Key-1:2/3!"} {
		if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey(key)); r.Code == http.StatusBadRequest {
			t.Fatalf("key %q: %s", key, r)
		}
	}
}

func TestIdempotencyKeysBelongToOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := openInvoice(t, e, e.Acme, "jane@acme.example")
	globex := openInvoice(t, e, e.Globex, "jane@globex.example")
	if r := e.DoWith("POST", payPath(acme), e.Acme.Key, visa, withKey("same")); r.Code != http.StatusOK {
		t.Fatalf("acme pay: %s", r)
	}
	if r := e.DoWith("POST", payPath(globex), e.Globex.Key, visa, withKey("same")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("globex pay with the same key: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 2 {
		t.Fatalf("%d charges, want 2", n)
	}
}

func TestIdempotencyKeyReusedForAnotherRequest(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	other := openInvoice(t, e, e.Acme, "john@acme.example")
	declined := map[string]string{"payment_method": "pm_card_declined"}
	first := e.DoWith("POST", payPath(inv), e.Acme.Key, declined, withKey("k"))
	if first.Code != http.StatusPaymentRequired {
		t.Fatalf("first pay: %s", first)
	}
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "idempotency_key_reused" {
		t.Fatalf("same invoice, other body: %s", r)
	}
	if r := e.DoWith("POST", payPath(other), e.Acme.Key, declined, withKey("k")); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "idempotency_key_reused" {
		t.Fatalf("other invoice: %s", r)
	}
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, declined, withKey("k")); r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "true" || string(r.Body) != string(first.Body) {
		t.Fatalf("retry after refusals: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("%d charge attempts, want 1", n)
	}
}

// holdFirstCharge makes the gateway hold the first charge until release is closed. It returns a channel that is closed
// when that charge has started.
func holdFirstCharge(e *apitest.Env) (started <-chan struct{}, release chan<- struct{}) {
	s, r := make(chan struct{}), make(chan struct{})
	var once sync.Once
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		once.Do(func() {
			close(s)
			<-r
		})
	}
	return s, r
}

func TestPayInFlightRefusesOtherRequestsAtOnce(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	started, release := holdFirstCharge(e)
	held := make(chan *apitest.Response, 1)
	go func() { held <- e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")) }()
	<-started

	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusConflict || r.Map(t)["error"] != "request_in_progress" {
		t.Fatalf("same key while in progress: %s", r)
	}
	if r := e.Do("POST", payPath(inv), e.Acme.Key, visa); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("no key while in progress: %s", r)
	}
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("other")); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("other key while in progress: %s", r)
	}
	close(release)
	if r := <-held; r.Code != http.StatusOK {
		t.Fatalf("held pay: %s", r)
	}
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry after the first finished: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

func TestServerErrorsAreNotKept(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	// With no body, the customer's default payment method is charged, so the retry can use a working method.
	setDefault := func(pm string) {
		t.Helper()
		if _, err := e.Store.UpdateCustomer(e.Acme.ID, inv.CustomerID, func(c *store.Customer) error {
			c.DefaultPaymentMethod = pm
			return nil
		}); err != nil {
			t.Fatal(err)
		}
	}
	setDefault("pm_gateway_down")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, nil, withKey("k")); r.Code != http.StatusServiceUnavailable || r.Map(t)["error"] != "gateway_unavailable" {
		t.Fatalf("first pay: %s", r)
	}
	setDefault("pm_card_visa")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, nil, withKey("k")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry after a server error should pay again: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

func TestKeptResponseExpiresAfter24Hours(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusOK {
		t.Fatalf("first pay: %s", r)
	}
	e.Clock.Advance(24*time.Hour - time.Minute)
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry before 24 hours: %s", r)
	}
	e.Clock.Advance(time.Minute)
	// The key counts as new now, and the invoice is already paid, so nothing is charged again.
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusConflict || r.Map(t)["error"] != "already_paid" || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry after 24 hours: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

