		if _, err := e.Store.UpdateCustomer(e.Acme.ID, inv.CustomerID, func(c *store.Customer) error {
			c.DefaultPaymentMethod = pm
			return nil
		}); err != nil {
			t.Fatal(err)
		}
	}
	setDefault("pm_gateway_down")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, nil, withKey("k")); r.Code != http.StatusServiceUnavailable || r.Map(t)["error"] != "gateway_unavailable" {
		t.Fatalf("first pay: %s", r)
	}
	setDefault("pm_card_visa")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, nil, withKey("k")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry after a server error should pay again: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

func TestKeptResponseExpiresAfter24Hours(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(t, e, e.Acme, "jane@acme.example")
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusOK {
		t.Fatalf("first pay: %s", r)
	}
	e.Clock.Advance(24*time.Hour - time.Minute)
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry before 24 hours: %s", r)
	}
	e.Clock.Advance(time.Minute)
	// The key counts as new now, and the invoice is already paid, so nothing is charged again.
	if r := e.DoWith("POST", payPath(inv), e.Acme.Key, visa, withKey("k")); r.Code != http.StatusConflict || r.Map(t)["error"] != "already_paid" || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry after 24 hours: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

package store

import (
	"bytes"
	"testing"
	"time"
)

func TestIdempotencyKeys(t *testing.T) {
	s := New()
	now := time.Date(2026, 3, 1, 9, 0, 0, 0, time.UTC)
	expect := func(what string, org, key, fp string, at time.Time, want IdempotencyState) IdempotencyRecord {
		t.Helper()
		r, got := s.BeginIdempotency(org, key, fp, at)
		if got != want {
			t.Fatalf("%s: state %d, want %d", what, got, want)
		}
		return r
	}
	expect("new", "org_a", "k", "fp1", now, IdempotencyNew)
	expect("in flight", "org_a", "k", "fp1", now, IdempotencyInFlight)
	expect("other request while in flight", "org_a", "k", "fp2", now, IdempotencyMismatch)
	expect("other organization", "org_b", "k", "fp2", now, IdempotencyNew)
	s.ReleaseIdempotency("org_b", "k")
	s.ReleaseIdempotency("org_a", "k")

	expect("new again after release", "org_a", "k", "fp1", now, IdempotencyNew)
	s.KeepIdempotency("org_a", "k", 402, []byte(`{"error":"payment_declined"}`), now)
	r := expect("replay", "org_a", "k", "fp1", now.Add(time.Hour), IdempotencyReplay)
	if r.Status != 402 || !bytes.Equal(r.Body, []byte(`{"error":"payment_declined"}`)) {
		t.Fatalf("replayed %d %s", r.Status, r.Body)
	}
	expect("other request after keeping", "org_a", "k", "fp2", now, IdempotencyMismatch)
	expect("expired", "org_a", "k", "fp1", now.Add(IdempotencyTTL), IdempotencyNew)
	s.ReleaseIdempotency("org_a", "k")
}

func TestIdempotencyKeysAreSaved(t *testing.T) {
	s := New()
	now := time.Date(2026, 3, 1, 9, 0, 0, 0, time.UTC)
	s.BeginIdempotency("org_a", "kept", "fp1", now)
	s.KeepIdempotency("org_a", "kept", 200, []byte(`{"ok":true}`), now)
	s.BeginIdempotency("org_a", "reserved", "fp2", now)

	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if r, st := s2.BeginIdempotency("org_a", "kept", "fp1", now); st != IdempotencyReplay || r.Status != 200 {
		t.Fatalf("kept response after reload: state %d, %+v", st, r)
	}
	if _, st := s2.BeginIdempotency("org_a", "reserved", "fp2", now); st != IdempotencyNew {
		t.Fatalf("a reserved key was saved: state %d", st)
	}
}

